from lib import *
S = SS('h11')
steps = [
    step("grpc.NewClient 是惰性的:创建后 200 ms,状态是 IDLE,代理看到的 TCP 连接 0 条;第一次调用之后状态 READY,TCP 连接 1 条;再调用 20 次,仍然是同一条连接(1 条)。另建一个 ClientConn 只调用 Connect()、不发请求,状态也变成 READY,TCP 连接累计 2 条。一个 ClientConn 默认对应一条 HTTP/2 连接,所有调用都复用它;创建 ClientConn 不会连接,要等第一次调用或显式 Connect()。", t=tl(S(1)), done=lidx(S(1), '另一个 ClientConn 只调用 Connect()'), mark=lidx(S(1), 'NewClient 之后 200 ms'), b=bars([['NewClient 之后 TCP 连接', 0, '0'], ['第一次调用之后', 1, '1'], ['再调用 20 次之后', 1, '1']], 2, mark=[0], done=[1, 2]), kv=KV([['NewClient', '状态 IDLE,0 条连接'], ['第一次调用', '建立 1 条连接,READY'], ['后续 20 次', '复用同一条']], ['NewClient'])),
    step("多个后端地址:pick_first(默认)30 次调用之后,三个后端各自收到的 TCP 连接数是 [1 0 0]——只连第一个;round_robin 是 [1 1 1]——同时连了所有三个。一个 ClientConn 里每个后端地址对应一个子连接(subchannel);pick_first 只用一个,round_robin 为每个地址都建一条并轮流使用。负载均衡策略决定了一个 ClientConn 实际有几条 TCP 连接(第 14 篇)。", t=tl(S(2)), done=lidx(S(2), 'round_robin'), mark=lidx(S(2), 'pick_first'), b=bars([['pick_first:连接数', 1, '1'], ['round_robin:连接数', 3, '3']], 3.5, mark=[0], done=[1]), kv=KV([['pick_first', '3 个地址只连 1 个'], ['round_robin', '3 个地址各建 1 条连接'], ['子连接', '每个后端地址一条(subchannel)']], ['子连接'])),
    step("连不上时的重连退避:一个“接受连接后立刻关闭”的假后端,默认退避下 11 秒内客户端尝试连接了 5 次,时刻 0.00、1.00、2.56、4.80、9.59 秒(间隔 1.00、1.55、2.24、4.79 秒);按 grpc-go 源码默认值 BaseDelay 1 s、Multiplier 1.6、Jitter 0.2、MaxDelay 120 s,间隔大约是 1、1.6、2.56、4.1 秒再加减 20% 的随机抖动。自定义退避(基础 100 ms、倍数 2、抖动 0、最大 1 s):11 秒内 14 次,间隔 0.10、0.20、0.40、0.80,然后固定 1.00 秒。退避期间连接状态是 TRANSIENT_FAILURE。", t=tl(S(3)), done=lidx(S(3), '自定义退避'), mark=lidx(S(3), '默认退避:'), b=bars([['默认退避 11 秒内尝试', 5, '5'], ['自定义退避 11 秒内尝试', 14, '14']], 15, mark=[0], done=[1]), kv=KV([['默认', '间隔 1.00、1.55、2.24、4.79 秒…(上限 120 秒)'], ['自定义', '0.1 → 0.2 → 0.4 → 0.8 → 固定 1.0 秒'], ['退避期间', '状态 TRANSIENT_FAILURE']], ['默认'])),
    step("连接断开后:服务端直接 Stop 时正在进行的慢调用 0.2 ms 后返回 code=Unavailable message=“error reading from server: EOF”;连接状态变成 IDLE(不是 TRANSIENT_FAILURE——它在等下一次调用再重连);之后第一次新调用(fail-fast)触发重连,但服务端还没起来,0.3 ms 返回 Unavailable;服务端重启后用 WaitForReady(true) 调用,等了 301.2 ms(正好是我设的 300 ms 基础退避)重连成功后调用成功,状态 READY。连接断开以后客户端不会立刻自己重连,要等下一次调用;fail-fast 的调用在退避期间会立刻失败。", t=tl(S(4)), done=lidx(S(4), '服务端重启后用 WaitForReady'), mark=lidx(S(4), '服务端 Stop 之后'), b=bars([['在途调用失败用时 ms', 0.2, '0.2'], ['退避期间 fail-fast 调用 ms', 0.3, '0.3'], ['WaitForReady 等待 ms', 301.2, '301.2']], 305, mark=[0, 1], done=[2]), kv=KV([['在途调用', 'Unavailable: error reading from server: EOF'], ['断开后状态', 'IDLE,等下一次调用才重连'], ['WaitForReady', '等到退避结束重连成功,301.2 ms']], ['断开后状态'])),
    step("GracefulStop:服务端发出两个 GOAWAY——第一个最后流 ID 是 2147483647(最大值,意思是“我要关了,但还不知道处理到哪一个”),第二个最后流 ID 是 3(实际处理到的最后一个流),错误码都是 NO_ERROR,附加数据 graceful_stop。在途的慢调用正常完成(err=<nil>,399.4 ms 后);GracefulStop 开始后发起的新调用失败:Unavailable,“error reading server preface: … connection reset by peer”——旧连接不再接受新流,新建连接又被拒绝(服务端已关闭监听),连接状态 TRANSIENT_FAILURE。两阶段 GOAWAY 是 HTTP/2 优雅关闭的标准做法。", t=tl(S(5)), done=lidx(S(5), '在途的慢调用'), mark=lidx(S(5), '线上 S→C GOAWAY'), b=bars([['GOAWAY 个数', 2, '2'], ['在途调用完成用时 ms', 399.4, '399.4']], 410, done=[0, 1]), kv=KV([['第一个 GOAWAY', '最后流 2147483647'], ['第二个 GOAWAY', '最后流 3'], ['在途调用', '完成;新调用 Unavailable']], ['第二个 GOAWAY'])),
    step("空闲超时:WithIdleTimeout(300 ms)——第一次调用之后状态 READY,TCP 连接 1 条;空闲 700 ms 之后状态 IDLE(客户端主动关闭了 TCP 连接);再调用一次用了 2.1 ms,状态回到 READY,TCP 连接累计 2 条(重新建立了连接)。默认的空闲超时很长(读 dialoptions.go 里 WithIdleTimeout 的注释:30 分钟),这里调短只是为了在实验里看到。长期空闲的服务如果前面有会杀空闲连接的 NAT 或负载均衡,可以把空闲超时设短于它们的超时,避免用到一条已经被悄悄断掉的连接。", t=tl(S(6)), done=lidx(S(6), '再调用一次'), mark=lidx(S(6), '空闲 700 ms 后'), b=bars([['第一次调用后 TCP 连接', 1, '1'], ['空闲后再调用,累计 TCP 连接', 2, '2']], 3, done=[1]), kv=KV([['空闲 700 ms(超时 300 ms)', '状态 IDLE,客户端关闭了连接'], ['再次调用', '2.1 ms,重新建立连接'], ['默认空闲超时', '30 分钟(读源码注释,没有等够 30 分钟测)']], ['空闲 700 ms(超时 300 ms)'])),
]
A = mkarth('h11', 11, 'gRPC,连接管理,ClientConn,重连,退避,GOAWAY,空闲超时,Go,真实验证,动画演示',
    '实测 gRPC 客户端连接管理:NewClient 惰性建连;pick_first 只连一个地址、round_robin 连全部;默认退避 1 秒起乘 1.6;断开后进入 IDLE 等下一次调用;GracefulStop 发两个 GOAWAY;WithIdleTimeout 让空闲连接回到 IDLE。',
    'gRPC 的 ClientConn 到底管着几条连接?什么时候建立?连接断了怎么重连、隔多久?服务端优雅关闭时客户端看到什么?空闲连接会被关吗?这篇逐项验证。',
    [('0 条', 'grpc.NewClient 之后、第一次调用之前的 TCP 连接数(惰性建连)'), ('1.00、1.55、2.24、4.79 秒', '默认退避下相邻两次重连尝试的间隔'), ('2147483647 → 3', 'GracefulStop 时两个 GOAWAY 里的最后流 ID')],
    [('惰性建连', '<p>grpc.NewClient 不会连接,创建后状态是 IDLE。第一次调用或 Connect() 才建 TCP 连接;之后所有调用复用这一条。</p>'),
     ('一个 ClientConn 几条连接', '<p>每个后端地址一个子连接。pick_first 只连一个地址;round_robin 对所有地址都建连接并轮流使用(第 14 篇)。</p>'),
     ('重连退避', '<p>连不上时按指数退避重试:默认基础 1 秒、倍数 1.6、抖动 20%、最长 120 秒(读源码 backoff/backoff.go)。可以用 WithConnectParams 调整。</p>'),
     ('断开之后', '<p>连接断开后客户端进入 IDLE,等下一次调用才重连;fail-fast 调用在退避期间立即失败,WaitForReady 会等到重连成功。</p>'),
     ('GracefulStop', '<p>服务端先发最后流 ID 为 2147483647 的 GOAWAY,再发带真实最后流 ID 的 GOAWAY;在途调用完成,新调用失败。</p>'),
     ('空闲超时', '<p>WithIdleTimeout 让空闲的连接关闭并回到 IDLE,下一次调用重新建立,可避开被中间设备悄悄断掉的连接(第 40 篇)。</p>')],
    steps,
    [ENV_H + '。第三节的“假后端”是只 Accept 就 Close 的 TCP 监听,时刻是它记录的相对时间;退避的默认值是读 backoff/backoff.go 得到的;第二节用 resolver/manual 提供三个地址;第四节自定义了退避(基础 300 ms),所以 WaitForReady 等了约 301 ms;其余是测量',
     '没有验证:默认空闲超时 30 分钟(只读了源码注释,没有等够 30 分钟去测);MinConnectTimeout 的作用;连接建立过程中的 TLS 握手耗时;DNS 解析器何时重新解析;服务端 max_connection_age 触发的 GOAWAY(第 40 篇);多个 ClientConn 共享一个后端时服务端的连接数'],
    '连接管理')
